const fs=require('fs');
const cp=require('child_process');
const {JSDOM,VirtualConsole}=require('jsdom');
const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN;
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}`;const assert=(v,m)=>{if(!v)throw new Error(m)};
async function req(url,options={}){const r=await fetch(url,{...options,headers:{...headers,...(options.headers||{})}});if(!r.ok)throw new Error(`${options.method||'GET'} ${url}: ${r.status} ${await r.text()}`);return r.json()}
async function get(path){const f=await req(`${api}/contents/${path}?ref=main`);return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function patchIndex(text){
 const manifest='<script src="../siza-core/manifest-rules.js"></script>',crystal='<script src="../siza-core/crystal-rules.js"></script>';assert(text.includes(manifest),'manifest tag missing');assert(!text.includes(crystal),'crystal tag already linked');let out=text.replace(manifest,manifest+'\n'+crystal);
 const pairs=[
 ["function crystalReqV070(c){const r={};for(const[k,n]of Object.entries(c?.pips||{}))if(n>0)r[k]=n;return r}","function crystalReqV070(c){return SizaCrystalRules.crystalReq(c)}"],
 ["function spellCostV070(c){return c?.type==='Land'?0:Math.max(1,Object.values(crystalReqV070(c)).reduce((a,b)=>a+b,0))}","function spellCostV070(c){return SizaCrystalRules.spellCost(c)}"],
 ["function directPlanV070(P,c){const req=crystalReqV070(c),spent={};for(const[k,n]of Object.entries(req)){if((P.crystals?.[k]||0)<n)return null;spent[k]=n}if(!Object.keys(req).length){const opts=['U','R','G','W','B'].filter(k=>(P.crystals?.[k]||0)>0);return opts.length?{kind:'flex',options:opts}:null}return{kind:'direct',spent}}","function directPlanV070(P,c){return SizaCrystalRules.directPlan(P,c)}"]];
 for(const[p,n]of pairs){assert(out.includes(p),'runtime anchor missing');out=out.replace(p,n)}return out
}
function inline(html,files,crystal){let out=html;for(const name of ['card-effects.js','card-schema.js','cards.js','card-renderer.js','manifest-rules.js',...(crystal?['crystal-rules.js']:[])]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`missing ${name}`);out=out.replace(tag,`<script>${files[name]}</script>`)}return out}
function dom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));const d=new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc});d.window.setTimeout=()=>0;return d}
(async()=>{const current=await get('siza-mobile-test/index.html'),candidate=patchIndex(current.text);const names=['card-effects.js','card-schema.js','cards.js','card-renderer.js','manifest-rules.js','crystal-rules.js'],files={};for(const n of names)files[n]=(await get(`siza-core/${n}`)).text;const marker='window.SIZA={',probe=`window.__CR__={crystalReqV070,spellCostV070,directPlanV070,cardById};\n`;const O=dom(inline(current.text,files,false).replace(marker,probe+marker),'old'),N=dom(inline(candidate,files,true).replace(marker,probe+marker),'new'),o=O.window.__CR__,n=N.window.__CR__;const cards=['mist','spark','servitor','ignimite','counter','prism','watcher','smuggler','tideblade','leviathan','dock','cinder','queen'].map(id=>o.cardById(id)).concat([{id:'none',type:'Creature',cost:9,pips:{}},{id:'odd',type:'Creature',pips:{U:2,R:1,G:0}}]),pools=[{crystals:{U:2,R:1,G:0,W:0,B:0}},{crystals:{U:1,R:1,G:1,W:1,B:1}},{crystals:{U:0,R:0,G:0,W:0,B:0}}];for(const c of cards){assert(JSON.stringify(o.crystalReqV070(c))===JSON.stringify(n.crystalReqV070(c)),`req ${c.id}`);assert(o.spellCostV070(c)===n.spellCostV070(c),`cost ${c.id}`);for(const p of pools)assert(JSON.stringify(o.directPlanV070(p,c))===JSON.stringify(n.directPlanV070(p,c)),`plan ${c.id}`)}const a=O.window.SIZA.runArenaCriticalV071(),b=N.window.SIZA.runArenaCriticalV071();assert(a.passed===a.total&&b.passed===b.total,`Arena ${a.passed}/${a.total} -> ${b.passed}/${b.total}`);O.window.close();N.window.close();console.log(`PASS runtime crystal equivalence; Arena ${b.passed}/${b.total}`);
 fs.mkdirSync('siza-mobile-test',{recursive:true});fs.writeFileSync('siza-mobile-test/index.html',candidate);for(const name of names){fs.mkdirSync('siza-core',{recursive:true});fs.writeFileSync(`siza-core/${name}`,files[name])}for(const path of ['.github/scripts/siza-arena-regression.js','.github/scripts/siza-combat-effects-regression.js','.github/scripts/siza-prism-effects-regression.js','.github/scripts/siza-equipment-effects-regression.js','.github/scripts/siza-battlefield-ui-index-regression.js']){const f=await get(path);fs.mkdirSync('.github/scripts',{recursive:true});fs.writeFileSync(path,f.text);cp.execFileSync('node',[path],{stdio:'inherit'})}
 const result=await req(`${api}/contents/siza-mobile-test/index.html`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Connect Arena to shared crystal payment rules',content:Buffer.from(candidate,'utf8').toString('base64'),sha:current.sha,branch:'main'})});console.log('COMMIT '+result.commit.sha)
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
